/// <summary>
/// Data contract class for updating pallet-related quantities in
/// Default Order Settings (CartonPerPallet, PalletLayerQty, PalletQty).
/// </summary>
[DataContract]
class METInventItemOrderSetupUpdatePalletQuantitiesContract extends METSysOperationTaskDataContract implements SysOperationInitializable
{
    guid                 topPickingProcessId;
    str                  packedQuery;

}

Method.Source:
/// <summary>
/// Gets or sets the number of threads to be used for batch execution.
/// Controls parallel processing efficiency during repricing.
/// </summary>
/// <param name="_threadCount">Thread count value.</param>
/// <returns>The current thread count.</returns>
[DataMember,
 SysOperationDisplayOrder('1'),
 SysOperationControlVisibilityAttribute(true)]
public METThreadCount parmThreadCount(METThreadCount _threadCount = threadCount)
{
    threadCount = _threadCount;
    return threadCount;
}

/// <summary>
/// Gets or sets the unique identifier for the top picking process.
/// Used to track and associate batch execution with a specific process instance.
/// </summary>
/// <param name="_topPickingProcessId">Process identifier (GUID).</param>
/// <returns>The current process identifier.</returns>
[DataMember,
 SysOperationDisplayOrder('2'),
 SysOperationControlVisibility(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;
    return topPickingProcessId;
}

/// <summary>
/// Gets or sets the packed query string used to define Sales Order selection criteria.
/// </summary>
/// <param name="_packedQuery">Base64-encoded query string.</param>
/// <returns>The current packed query string.</returns>
[DataMemberAttribute,
 AifQueryTypeAttribute('_packedQuery', queryStr(METInventItemOrderSetupQuery))]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Decodes the packed query string and returns a Query object.
/// </summary>
/// <returns>A Query object constructed from the packed query.</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}
